mapper.select:
select c.*, m.name as from_member_name
from hys_commission c
left join hys_member m on m.member_id = c.from_member_id

    and c.beneficiary_id = #{beneficiaryId}
    and c.level = #{level}
    and c.status = #{status}
    and c.order_id like concat('%', #{orderId}, '%')

order by c.commission_id desc
